// Build a concise LINE alert from the Error Trigger payload.
const j = $input.first().json || {};
const ex = j.execution || {};
const err = ex.error || {};
const wf = j.workflow || {};
const code = err.httpCode || err.code || err.name || err.errorCode || '';
const desc = err.description || err.message || (typeof err === 'string' ? err : '') || 'Unknown error';
const nodeName = (err.node && err.node.name) || ex.lastNodeExecuted || '';
const when = new Date().toISOString();

let text = '\u26A0\uFE0F Backup FAILED\n';
text += 'Workflow: ' + (wf.name || '(unknown)') + '\n';
if (nodeName) text += 'Node: ' + nodeName + '\n';
if (code) text += 'Code: ' + String(code) + '\n';
text += 'Error: ' + String(desc).slice(0, 400) + '\n';
text += 'Exec: ' + String(ex.id || '') + '\n';
text += 'Time: ' + when + '\n';
text += '\u2757 Old backups were NOT deleted (delete only runs after a verified-complete backup).';

return [{ json: { alert_text: text.slice(0, 4900) } }];
